import{_ as t,o as i,c as d,b as l}from"./index-C1GwWGto.js";const v={},o={class:"help-page"};function u(e,a){return i(),d("div",o,[...a[0]||(a[0]=[l('<div class="container" data-v-99027aa7><h2 data-v-99027aa7>📖 使用指南</h2><div class="guide-section" data-v-99027aa7><h3 data-v-99027aa7>1. 注册与登录</h3><ul data-v-99027aa7><li data-v-99027aa7>点击首页右上角&quot;注册&quot;按钮，填写手机号和密码完成注册</li><li data-v-99027aa7>注册成功后自动登录，也可使用手机号和密码手动登录</li><li data-v-99027aa7>支持手机号验证码登录</li></ul></div><div class="guide-section" data-v-99027aa7><h3 data-v-99027aa7>2. 宠物档案管理</h3><ul data-v-99027aa7><li data-v-99027aa7>登录后进入&quot;宠物档案&quot;页面</li><li data-v-99027aa7>点击&quot;添加宠物&quot;按钮，填写宠物基本信息</li><li data-v-99027aa7>可以管理宠物的疫苗记录和健康档案</li></ul></div><div class="guide-section" data-v-99027aa7><h3 data-v-99027aa7>3. 预约门店服务</h3><ul data-v-99027aa7><li data-v-99027aa7>进入&quot;门店服务&quot;页面，浏览或搜索附近门店</li><li data-v-99027aa7>点击&quot;查看服务&quot;查看门店提供的服务项目</li><li data-v-99027aa7>选择服务后点击&quot;预约&quot;，填写预约日期和时间</li><li data-v-99027aa7>提交预约后可在&quot;我的订单&quot;查看预约状态</li></ul></div><div class="guide-section" data-v-99027aa7><h3 data-v-99027aa7>4. 商城购物</h3><ul data-v-99027aa7><li data-v-99027aa7>进入&quot;商城&quot;页面，浏览各类宠物商品</li><li data-v-99027aa7>点击&quot;加入购物车&quot;将商品添加到购物车</li><li data-v-99027aa7>在购物车页面修改数量或删除商品</li><li data-v-99027aa7>点击&quot;结算&quot;完成订单支付</li></ul></div><div class="guide-section" data-v-99027aa7><h3 data-v-99027aa7>5. 养宠社区</h3><ul data-v-99027aa7><li data-v-99027aa7>进入&quot;社区&quot;页面浏览其他用户发布的帖子</li><li data-v-99027aa7>点击&quot;发布帖子&quot;分享养宠心得</li><li data-v-99027aa7>可以对帖子进行点赞和评论</li><li data-v-99027aa7>支持发布寻宠启事</li></ul></div></div>',1)])])}const c=t(v,[["render",u],["__scopeId","data-v-99027aa7"]]);export{c as default};
